class Ingredient extends DataClass implements Insertable<Ingredient> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final String businessId;
  final String name;
  final IngredientCategory category;
  final BaseUnit baseUnit;

  /// Ambang stok menipis, dalam satuan dasar.
  final double minStock;

  /// Cache saldo dari [StockMovements]; bisa dihitung ulang dari ledger.
  final double currentStock;

  /// Rp per satuan dasar, rata-rata tertimbang. Kosong = belum ada harga,
  /// sehingga HPP menu yang memakainya belum lengkap.
  final double? avgUnitCost;

  /// Harga masih perkiraan (FR-1.7); menjadi false setelah belanja pertama.
  final bool priceIsEstimate;
  final bool lowStockNotified;
  final String? note;
  const Ingredient({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.businessId,
    required this.name,
    required this.category,
    required this.baseUnit,
    required this.minStock,
    required this.currentStock,
    this.avgUnitCost,
    required this.priceIsEstimate,
    required this.lowStockNotified,
    this.note,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['business_id'] = Variable<String>(businessId);
    map['name'] = Variable<String>(name);
    {
      map['category'] = Variable<String>(
        $IngredientsTable.$convertercategory.toSql(category),
      );
    }
    {
      map['base_unit'] = Variable<String>(
        $IngredientsTable.$converterbaseUnit.toSql(baseUnit),
      );
    }
    map['min_stock'] = Variable<double>(minStock);
    map['current_stock'] = Variable<double>(currentStock);
    if (!nullToAbsent || avgUnitCost != null) {
      map['avg_unit_cost'] = Variable<double>(avgUnitCost);
    }
    map['price_is_estimate'] = Variable<bool>(priceIsEstimate);
    map['low_stock_notified'] = Variable<bool>(lowStockNotified);
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    return map;
  }

  IngredientsCompanion toCompanion(bool nullToAbsent) {
    return IngredientsCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      businessId: Value(businessId),
      name: Value(name),
      category: Value(category),
      baseUnit: Value(baseUnit),
