    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['purchase_id'] = Variable<String>(purchaseId);
    map['ingredient_id'] = Variable<String>(ingredientId);
    map['qty'] = Variable<double>(qty);
    map['unit_name'] = Variable<String>(unitName);
    map['factor_to_base'] = Variable<double>(factorToBase);
    map['qty_base'] = Variable<double>(qtyBase);
    map['total_price'] = Variable<int>(totalPrice);
    map['unit_cost_base'] = Variable<double>(unitCostBase);
    return map;
  }

  PurchaseItemsCompanion toCompanion(bool nullToAbsent) {
    return PurchaseItemsCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      purchaseId: Value(purchaseId),
      ingredientId: Value(ingredientId),
      qty: Value(qty),
      unitName: Value(unitName),
      factorToBase: Value(factorToBase),
      qtyBase: Value(qtyBase),
      totalPrice: Value(totalPrice),
      unitCostBase: Value(unitCostBase),
    );
  }

  factory PurchaseItem.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return PurchaseItem(
      id: serializer.fromJson<String>(json['id']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      deletedAt: serializer.fromJson<DateTime?>(json['deletedAt']),
      purchaseId: serializer.fromJson<String>(json['purchaseId']),
