      unitName: serializer.fromJson<String>(json['unitName']),
      factorToBase: serializer.fromJson<double>(json['factorToBase']),
      qtyBase: serializer.fromJson<double>(json['qtyBase']),
      totalPrice: serializer.fromJson<int>(json['totalPrice']),
      unitCostBase: serializer.fromJson<double>(json['unitCostBase']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
