class StockMovement extends DataClass implements Insertable<StockMovement> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final String ingredientId;
  final MovementType type;

  /// Positif = masuk, negatif = keluar.
  final double qtyBase;
  final double unitCost;

  /// qtyBase × unitCost, dibulatkan ke Rupiah.
  final int value;
  final double balanceAfter;
  final double avgCostAfter;

  /// Sumber mutasi: `purchase_item`, `production`, `order`; kosong untuk stok
  /// awal dan penyesuaian manual.
  final String? refType;
  final String? refId;

  /// Diisi pada mutasi pembalik: id mutasi yang dibatalkan (FR-9.1).
  final String? reversalOfId;
  final DateTime occurredAt;
  final String? note;
  const StockMovement({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.ingredientId,
    required this.type,
    required this.qtyBase,
    required this.unitCost,
    required this.value,
    required this.balanceAfter,
    required this.avgCostAfter,
    this.refType,
    this.refId,
    this.reversalOfId,
    required this.occurredAt,
    this.note,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['ingredient_id'] = Variable<String>(ingredientId);
    {
      map['type'] = Variable<String>(
        $StockMovementsTable.$convertertype.toSql(type),
      );
    }
    map['qty_base'] = Variable<double>(qtyBase);
    map['unit_cost'] = Variable<double>(unitCost);
    map['value'] = Variable<int>(value);
    map['balance_after'] = Variable<double>(balanceAfter);
    map['avg_cost_after'] = Variable<double>(avgCostAfter);
    if (!nullToAbsent || refType != null) {
      map['ref_type'] = Variable<String>(refType);
    }
    if (!nullToAbsent || refId != null) {
      map['ref_id'] = Variable<String>(refId);
    }
    if (!nullToAbsent || reversalOfId != null) {
      map['reversal_of_id'] = Variable<String>(reversalOfId);
    }
    map['occurred_at'] = Variable<DateTime>(occurredAt);
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    return map;
  }

  StockMovementsCompanion toCompanion(bool nullToAbsent) {
    return StockMovementsCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      ingredientId: Value(ingredientId),
      type: Value(type),
      qtyBase: Value(qtyBase),
      unitCost: Value(unitCost),
      value: Value(value),
      balanceAfter: Value(balanceAfter),
      avgCostAfter: Value(avgCostAfter),
      refType: refType == null && nullToAbsent
          ? const Value.absent()
          : Value(refType),
      refId: refId == null && nullToAbsent
          ? const Value.absent()
          : Value(refId),
      reversalOfId: reversalOfId == null && nullToAbsent
          ? const Value.absent()
          : Value(reversalOfId),
      occurredAt: Value(occurredAt),
      note: note == null && nullToAbsent ? const Value.absent() : Value(note),
    );
  }

