class Product extends DataClass implements Insertable<Product> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final String businessId;
  final String name;
  final String? category;
  final String? photoPath;
  final int sellingPrice;

  /// Hasil pcs per 1 resep.
  final double yieldQty;

  /// Menimpa markup bawaan usaha jika diisi.
  final double? targetMarkupPct;

  /// Kosong = ikut mode stok bawaan usaha.
  final StockDeductMode? stockDeductMode;
  final bool isActive;

  /// Cache HPP terkini; dihitung ulang saat harga bahan atau resep berubah.
  final double hppPerPcs;
  final DateTime? hppUpdatedAt;
  final HppStatus hppStatus;

  /// Cache saldo stok produk jadi dari [ProductStockMovements].
  final double currentStock;

  /// HPP rata-rata tertimbang stok produk jadi.
  final double stockUnitCost;

  /// Umur simpan dalam hari untuk produk ready stock (FR-4.10).
  final int? shelfLifeDays;

  /// Stok jaga: pcs yang ingin selalu tersedia, ikut dihitung di daftar
  /// belanja (FR-12.10). Skema v4.
  final double safetyStock;
  const Product({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    required this.businessId,
    required this.name,
    this.category,
    this.photoPath,
    required this.sellingPrice,
    required this.yieldQty,
    this.targetMarkupPct,
    this.stockDeductMode,
    required this.isActive,
    required this.hppPerPcs,
    this.hppUpdatedAt,
    required this.hppStatus,
    required this.currentStock,
    required this.stockUnitCost,
    this.shelfLifeDays,
    required this.safetyStock,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    map['business_id'] = Variable<String>(businessId);
    map['name'] = Variable<String>(name);
    if (!nullToAbsent || category != null) {
      map['category'] = Variable<String>(category);
    }
    if (!nullToAbsent || photoPath != null) {
      map['photo_path'] = Variable<String>(photoPath);
    }
    map['selling_price'] = Variable<int>(sellingPrice);
    map['yield_qty'] = Variable<double>(yieldQty);
    if (!nullToAbsent || targetMarkupPct != null) {
      map['target_markup_pct'] = Variable<double>(targetMarkupPct);
    }
    if (!nullToAbsent || stockDeductMode != null) {
      map['stock_deduct_mode'] = Variable<String>(
        $ProductsTable.$converterstockDeductModen.toSql(stockDeductMode),
      );
    }
    map['is_active'] = Variable<bool>(isActive);
    map['hpp_per_pcs'] = Variable<double>(hppPerPcs);
    if (!nullToAbsent || hppUpdatedAt != null) {
      map['hpp_updated_at'] = Variable<DateTime>(hppUpdatedAt);
    }
    {
      map['hpp_status'] = Variable<String>(
        $ProductsTable.$converterhppStatus.toSql(hppStatus),
      );
    }
    map['current_stock'] = Variable<double>(currentStock);
    map['stock_unit_cost'] = Variable<double>(stockUnitCost);
    if (!nullToAbsent || shelfLifeDays != null) {
      map['shelf_life_days'] = Variable<int>(shelfLifeDays);
    }
    map['safety_stock'] = Variable<double>(safetyStock);
    return map;
  }

  ProductsCompanion toCompanion(bool nullToAbsent) {
    return ProductsCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      businessId: Value(businessId),
      name: Value(name),
      category: category == null && nullToAbsent
          ? const Value.absent()
          : Value(category),
      photoPath: photoPath == null && nullToAbsent
          ? const Value.absent()
          : Value(photoPath),
      sellingPrice: Value(sellingPrice),
      yieldQty: Value(yieldQty),
      targetMarkupPct: targetMarkupPct == null && nullToAbsent
          ? const Value.absent()
          : Value(targetMarkupPct),
      stockDeductMode: stockDeductMode == null && nullToAbsent
          ? const Value.absent()
          : Value(stockDeductMode),
      isActive: Value(isActive),
      hppPerPcs: Value(hppPerPcs),
      hppUpdatedAt: hppUpdatedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(hppUpdatedAt),
      hppStatus: Value(hppStatus),
      currentStock: Value(currentStock),
      stockUnitCost: Value(stockUnitCost),
      shelfLifeDays: shelfLifeDays == null && nullToAbsent
          ? const Value.absent()
          : Value(shelfLifeDays),
      safetyStock: Value(safetyStock),
    );
  }

  factory Product.fromJson(
    Map<String, dynamic> json, {
    ValueSerializer? serializer,
  }) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return Product(
      id: serializer.fromJson<String>(json['id']),
      createdAt: serializer.fromJson<DateTime>(json['createdAt']),
      updatedAt: serializer.fromJson<DateTime>(json['updatedAt']),
      deletedAt: serializer.fromJson<DateTime?>(json['deletedAt']),
      businessId: serializer.fromJson<String>(json['businessId']),
      name: serializer.fromJson<String>(json['name']),
      category: serializer.fromJson<String?>(json['category']),
      photoPath: serializer.fromJson<String?>(json['photoPath']),
      sellingPrice: serializer.fromJson<int>(json['sellingPrice']),
      yieldQty: serializer.fromJson<double>(json['yieldQty']),
      targetMarkupPct: serializer.fromJson<double?>(json['targetMarkupPct']),
      stockDeductMode: serializer.fromJson<StockDeductMode?>(
        json['stockDeductMode'],
      ),
      isActive: serializer.fromJson<bool>(json['isActive']),
      hppPerPcs: serializer.fromJson<double>(json['hppPerPcs']),
      hppUpdatedAt: serializer.fromJson<DateTime?>(json['hppUpdatedAt']),
      hppStatus: serializer.fromJson<HppStatus>(json['hppStatus']),
      currentStock: serializer.fromJson<double>(json['currentStock']),
      stockUnitCost: serializer.fromJson<double>(json['stockUnitCost']),
      shelfLifeDays: serializer.fromJson<int?>(json['shelfLifeDays']),
      safetyStock: serializer.fromJson<double>(json['safetyStock']),
    );
  }
  @override
  Map<String, dynamic> toJson({ValueSerializer? serializer}) {
    serializer ??= driftRuntimeOptions.defaultSerializer;
    return <String, dynamic>{
      'id': serializer.toJson<String>(id),
      'createdAt': serializer.toJson<DateTime>(createdAt),
      'updatedAt': serializer.toJson<DateTime>(updatedAt),
      'deletedAt': serializer.toJson<DateTime?>(deletedAt),
      'businessId': serializer.toJson<String>(businessId),
      'name': serializer.toJson<String>(name),
      'category': serializer.toJson<String?>(category),
      'photoPath': serializer.toJson<String?>(photoPath),
      'sellingPrice': serializer.toJson<int>(sellingPrice),
      'yieldQty': serializer.toJson<double>(yieldQty),
      'targetMarkupPct': serializer.toJson<double?>(targetMarkupPct),
      'stockDeductMode': serializer.toJson<StockDeductMode?>(stockDeductMode),
      'isActive': serializer.toJson<bool>(isActive),
      'hppPerPcs': serializer.toJson<double>(hppPerPcs),
      'hppUpdatedAt': serializer.toJson<DateTime?>(hppUpdatedAt),
      'hppStatus': serializer.toJson<HppStatus>(hppStatus),
      'currentStock': serializer.toJson<double>(currentStock),
      'stockUnitCost': serializer.toJson<double>(stockUnitCost),
      'shelfLifeDays': serializer.toJson<int?>(shelfLifeDays),
      'safetyStock': serializer.toJson<double>(safetyStock),
    };
  }

  Product copyWith({
    String? id,
    DateTime? createdAt,
    DateTime? updatedAt,
    Value<DateTime?> deletedAt = const Value.absent(),
    String? businessId,
    String? name,
    Value<String?> category = const Value.absent(),
    Value<String?> photoPath = const Value.absent(),
    int? sellingPrice,
    double? yieldQty,
    Value<double?> targetMarkupPct = const Value.absent(),
    Value<StockDeductMode?> stockDeductMode = const Value.absent(),
    bool? isActive,
    double? hppPerPcs,
    Value<DateTime?> hppUpdatedAt = const Value.absent(),
    HppStatus? hppStatus,
    double? currentStock,
    double? stockUnitCost,
    Value<int?> shelfLifeDays = const Value.absent(),
    double? safetyStock,
  }) => Product(
    id: id ?? this.id,
    createdAt: createdAt ?? this.createdAt,
    updatedAt: updatedAt ?? this.updatedAt,
    deletedAt: deletedAt.present ? deletedAt.value : this.deletedAt,
    businessId: businessId ?? this.businessId,
    name: name ?? this.name,
    category: category.present ? category.value : this.category,
    photoPath: photoPath.present ? photoPath.value : this.photoPath,
