        $ProductCostsTable.$convertercostType.toSql(costType),
      );
    }
    map['amount'] = Variable<int>(amount);
    {
      map['basis'] = Variable<String>(
        $ProductCostsTable.$converterbasis.toSql(basis),
      );
    }
    if (!nullToAbsent || laborHours != null) {
      map['labor_hours'] = Variable<double>(laborHours);
    }
    return map;
