class Order extends DataClass implements Insertable<Order> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final DateTime? voidedAt;
  final String? voidReason;
  final String businessId;

  /// mis. `PO-261019-001`, unik per usaha.
  final String orderNo;
  final String? customerId;

  /// Kosong = Langsung.
  final String? channelId;
  final OrderType type;
  final OrderStatus status;

  /// Tanggal + jam ambil/kirim.
  final DateTime dueAt;
  final Fulfillment fulfillment;
  final String? deliveryAddress;

  /// total = subtotal − discount + shippingFee. Ongkir bukan omzet.
  final int subtotal;
  final int discount;
  final int shippingFee;
  final int total;

  /// Potongan channel pesanan ini; otomatis dari channel, bisa diubah.
  final int channelFee;

  /// Cache jumlah [Payments].
  final int paidAmount;
  final PaymentStatus paymentStatus;
  final DateTime? completedAt;
  final DateTime? cancelledAt;
  final String? note;
  const Order({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    this.voidedAt,
    this.voidReason,
    required this.businessId,
    required this.orderNo,
    this.customerId,
    this.channelId,
    required this.type,
    required this.status,
    required this.dueAt,
    required this.fulfillment,
    this.deliveryAddress,
    required this.subtotal,
    required this.discount,
    required this.shippingFee,
    required this.total,
    required this.channelFee,
    required this.paidAmount,
    required this.paymentStatus,
    this.completedAt,
    this.cancelledAt,
    this.note,
  });
  @override
  Map<String, Expression> toColumns(bool nullToAbsent) {
    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    if (!nullToAbsent || voidedAt != null) {
      map['voided_at'] = Variable<DateTime>(voidedAt);
    }
    if (!nullToAbsent || voidReason != null) {
      map['void_reason'] = Variable<String>(voidReason);
    }
    map['business_id'] = Variable<String>(businessId);
    map['order_no'] = Variable<String>(orderNo);
    if (!nullToAbsent || customerId != null) {
      map['customer_id'] = Variable<String>(customerId);
    }
    if (!nullToAbsent || channelId != null) {
      map['channel_id'] = Variable<String>(channelId);
    }
    {
      map['type'] = Variable<String>($OrdersTable.$convertertype.toSql(type));
    }
    {
      map['status'] = Variable<String>(
        $OrdersTable.$converterstatus.toSql(status),
      );
    }
    map['due_at'] = Variable<DateTime>(dueAt);
    {
      map['fulfillment'] = Variable<String>(
