    }
    if (!nullToAbsent || deliveryAddress != null) {
      map['delivery_address'] = Variable<String>(deliveryAddress);
    }
    map['subtotal'] = Variable<int>(subtotal);
    map['discount'] = Variable<int>(discount);
    map['shipping_fee'] = Variable<int>(shippingFee);
    map['total'] = Variable<int>(total);
    map['channel_fee'] = Variable<int>(channelFee);
    map['paid_amount'] = Variable<int>(paidAmount);
    {
      map['payment_status'] = Variable<String>(
        $OrdersTable.$converterpaymentStatus.toSql(paymentStatus),
      );
    }
    if (!nullToAbsent || completedAt != null) {
      map['completed_at'] = Variable<DateTime>(completedAt);
    }
    if (!nullToAbsent || cancelledAt != null) {
      map['cancelled_at'] = Variable<DateTime>(cancelledAt);
    }
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    return map;
  }

