class Production extends DataClass implements Insertable<Production> {
  final String id;
  final DateTime createdAt;
  final DateTime updatedAt;
  final DateTime? deletedAt;
  final DateTime? voidedAt;
  final String? voidReason;
  final String businessId;
  final String productId;
  final String? orderId;

  /// Jumlah resep (boleh desimal) dan hasil pcs.
  final double batchQty;
  final double outputQty;
  final int materialCost;
  final int otherCost;

  /// Snapshot HPP saat produksi.
  final double hppPerPcs;
  final DateTime producedAt;
  final String? note;
  const Production({
    required this.id,
    required this.createdAt,
    required this.updatedAt,
    this.deletedAt,
    this.voidedAt,
    this.voidReason,
    required this.businessId,
    required this.productId,
    this.orderId,
    required this.batchQty,
    required this.outputQty,
