    final map = <String, Expression>{};
    map['id'] = Variable<String>(id);
    map['created_at'] = Variable<DateTime>(createdAt);
    map['updated_at'] = Variable<DateTime>(updatedAt);
    if (!nullToAbsent || deletedAt != null) {
      map['deleted_at'] = Variable<DateTime>(deletedAt);
    }
    if (!nullToAbsent || voidedAt != null) {
      map['voided_at'] = Variable<DateTime>(voidedAt);
    }
    if (!nullToAbsent || voidReason != null) {
      map['void_reason'] = Variable<String>(voidReason);
    }
    map['business_id'] = Variable<String>(businessId);
    map['product_id'] = Variable<String>(productId);
    if (!nullToAbsent || orderId != null) {
      map['order_id'] = Variable<String>(orderId);
    }
    map['batch_qty'] = Variable<double>(batchQty);
    map['output_qty'] = Variable<double>(outputQty);
    map['material_cost'] = Variable<int>(materialCost);
    map['other_cost'] = Variable<int>(otherCost);
    map['hpp_per_pcs'] = Variable<double>(hppPerPcs);
    map['produced_at'] = Variable<DateTime>(producedAt);
    if (!nullToAbsent || note != null) {
      map['note'] = Variable<String>(note);
    }
    return map;
  }

  ProductionsCompanion toCompanion(bool nullToAbsent) {
    return ProductionsCompanion(
      id: Value(id),
      createdAt: Value(createdAt),
      updatedAt: Value(updatedAt),
      deletedAt: deletedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(deletedAt),
      voidedAt: voidedAt == null && nullToAbsent
          ? const Value.absent()
          : Value(voidedAt),
